def sync_public_cells(name, cells):
    spec = CHANGES.get(name)
    if spec is None:
        return cells
    for before, after in spec['replacements']:
        matches = [c for c in cells if c.source == before]
        if len(matches) != 1:
            raise ValueError(f'{name}: expected one reviewed source match, got {len(matches)}')
        matches[0].source = after
    cells.extend(nbf.v4.new_markdown_cell('') for _ in range(spec['empty_markdown']))
    return cells
